@parity "dart2wasm/lib/dynamic_dispatch_table.dart:49 DynamicDispatchTable.getClassIdsTable" get_class_ids_table(self::DynamicDispatchTable, module_::WasmBuilder.ModuleBuilder)::WasmBuilder.IR.AbstractTable =
